// Functor (callable object) definition
class StatefulMultiplier {
    int factor_;
public:
    explicit StatefulMultiplier(int f) : factor_(f) {}

    // Overloading the function call operator
    // Must be const if it doesn't modify functor state
    int operator()(int value) const {
        return value * factor_;
    }
};

